
%% BME331 Lab 3: Part 1 Complete Data Analysis Script
clear; clc; close all;

disp('Starting Data Processing...'); %[output:46ee0d4c]

%% SECTION 1: Data Loading & Cleanup
% Load Force Plate Data (.txt files)
fp_quietEO = load('quietEO.txt');
fp_quietEC = load('quietEC.txt');
fp_ropeEC  = load('quietropeEC.txt');

% Fix the corrupted data: Remove the last 20 rows of zeros
fp_ropeEC(end-19:end, :) = []; 

% Load EMG Data (.data files)
emg_quietEO = load('quieteo.data'); 
emg_quietEC = load('quietec.data');
emg_ropeEC  = load('quietropeec.data');

% Extract SOL (Col 1) and TA (Col 2)
SOL_EO_raw = emg_quietEO(:, 1); TA_EO_raw  = emg_quietEO(:, 2);
SOL_EC_raw = emg_quietEC(:, 1); TA_EC_raw  = emg_quietEC(:, 2);
SOL_rope_raw = emg_ropeEC(:, 1); TA_rope_raw  = emg_ropeEC(:, 2);

%% SECTION 2: COP Calculation & Interpolation
dz = 41.3; % Force plate thickness in mm [cite: 133]
fs_fp = 200; fs_emg = 960; % [cite: 143]

calc_ML = @(fp) -1000*(fp(:,5) + fp(:,1)*dz/1000) ./ fp(:,3); % [cite: 134]
calc_AP = @(fp)  1000*(fp(:,4) - fp(:,2)*dz/1000) ./ fp(:,3); % [cite: 135]

% Calculate raw COP
ML_EO_raw = calc_ML(fp_quietEO); AP_EO_raw = calc_AP(fp_quietEO);
ML_EC_raw = calc_ML(fp_quietEC); AP_EC_raw = calc_AP(fp_quietEC);
ML_rope_raw = calc_ML(fp_ropeEC); AP_rope_raw = calc_AP(fp_ropeEC);

% Interpolation function [cite: 144]
upsample_fp = @(cop_signal) interp1(0:1/fs_fp:(length(cop_signal)-1)/fs_fp, ...
                                    cop_signal, ...
                                    0:1/fs_emg:(length(cop_signal)-1)/fs_fp, 'spline')';

% Apply interpolation
AP_EO_up = upsample_fp(AP_EO_raw); ML_EO_up = upsample_fp(ML_EO_raw);
AP_EC_up = upsample_fp(AP_EC_raw); ML_EC_up = upsample_fp(ML_EC_raw);
AP_rope_up = upsample_fp(AP_rope_raw); ML_rope_up = upsample_fp(ML_rope_raw);

%% SECTION 3: Synchronization (Using your exact indices)
sync_idx_EO   = 9522; 
sync_idx_EC   = 8733; 
sync_idx_rope = 6628; 

% Truncate EMG data
SOL_EO_sync = SOL_EO_raw(sync_idx_EO:end); TA_EO_sync  = TA_EO_raw(sync_idx_EO:end);
SOL_EC_sync = SOL_EC_raw(sync_idx_EC:end); TA_EC_sync  = TA_EC_raw(sync_idx_EC:end);
SOL_rope_sync = SOL_rope_raw(sync_idx_rope:end); TA_rope_sync  = TA_rope_raw(sync_idx_rope:end);

% Match lengths
min_len_EO = min(length(AP_EO_up), length(SOL_EO_sync));
AP_EO = AP_EO_up(1:min_len_EO); ML_EO = ML_EO_up(1:min_len_EO);
SOL_EO = SOL_EO_sync(1:min_len_EO); TA_EO = TA_EO_sync(1:min_len_EO);

min_len_EC = min(length(AP_EC_up), length(SOL_EC_sync));
AP_EC = AP_EC_up(1:min_len_EC); ML_EC = ML_EC_up(1:min_len_EC);
SOL_EC = SOL_EC_sync(1:min_len_EC); TA_EC = TA_EC_sync(1:min_len_EC);

min_len_rope = min(length(AP_rope_up), length(SOL_rope_sync));
AP_rope = AP_rope_up(1:min_len_rope); ML_rope = ML_rope_up(1:min_len_rope);
SOL_rope = SOL_rope_sync(1:min_len_rope); TA_rope = TA_rope_sync(1:min_len_rope);

%% SECTION 4: Filtering
[b, a] = butter(4, 5/(fs_emg/2), 'low'); % 4th order, 5Hz cutoff [cite: 215, 217]

filter_cop = @(signal) filtfilt(b, a, signal) - mean(filtfilt(b, a, signal)); % Zero-mean [cite: 216]
filter_emg = @(signal) filtfilt(b, a, abs(signal - mean(signal)));

AP_EO_filt = filter_cop(AP_EO); ML_EO_filt = filter_cop(ML_EO);
SOL_EO_filt = filter_emg(SOL_EO); TA_EO_filt  = filter_emg(TA_EO);

AP_EC_filt = filter_cop(AP_EC); ML_EC_filt = filter_cop(ML_EC);
SOL_EC_filt = filter_emg(SOL_EC); TA_EC_filt  = filter_emg(TA_EC);

AP_rope_filt = filter_cop(AP_rope);
SOL_rope_filt = filter_emg(SOL_rope); TA_rope_filt  = filter_emg(TA_rope);

%% SECTION 5: Metrics & Reporting
time_EO = (0:length(AP_EO_filt)-1) / fs_emg;
time_EC = (0:length(AP_EC_filt)-1) / fs_emg;

calc_metrics = @(sig) [mean(abs(sig)), sqrt(mean(sig.^2)), max(sig)-min(sig), sum(abs(diff(sig)))/(length(sig)/fs_emg)]; % [cite: 221, 224, 227, 230]

metrics_AP_EO = calc_metrics(AP_EO_filt); metrics_ML_EO = calc_metrics(ML_EO_filt);
metrics_AP_EC = calc_metrics(AP_EC_filt); metrics_ML_EC = calc_metrics(ML_EC_filt);

fprintf('\n=== TABLE 1: COP MEASUREMENTS ===\n'); %[output:21fc3adc]
fprintf('EO AP: MDIST=%.2f mm, RDIST=%.2f mm, RANGE=%.2f mm, MVELO=%.2f mm/s\n', metrics_AP_EO); %[output:4cd7086b]
fprintf('EO ML: MDIST=%.2f mm, RDIST=%.2f mm, RANGE=%.2f mm, MVELO=%.2f mm/s\n', metrics_ML_EO); %[output:7a9213f6]
fprintf('EC AP: MDIST=%.2f mm, RDIST=%.2f mm, RANGE=%.2f mm, MVELO=%.2f mm/s\n', metrics_AP_EC); %[output:0627cda2]
fprintf('EC ML: MDIST=%.2f mm, RDIST=%.2f mm, RANGE=%.2f mm, MVELO=%.2f mm/s\n', metrics_ML_EC); %[output:0f424f20]

%% SECTION 6: Cross-Correlation (CCF)
seg_length = 8192; num_segments = 13; % [cite: 242]

function [avg_ccf, time_shift, CVAL, TS] = compute_ccf(emg, cop, seg_length, num_segments, fs)
    skip_time = 5; % seconds to discard
    skip_samples = skip_time * fs;
    ccf_seg = zeros(num_segments, 2*seg_length - 1);
    for k = 1:num_segments
        idx_start = (k-1)*seg_length + skip_samples + 1;
        idx_end   = idx_start + seg_length - 1;
        
        % Zero-mean the segments before cross-correlating
        e_seg = emg(idx_start:idx_end) - mean(emg(idx_start:idx_end));
        c_seg = cop(idx_start:idx_end) - mean(cop(idx_start:idx_end));
        
        ccf_seg(k, :) = xcorr(e_seg, c_seg, 'coeff');
    end
    
    avg_ccf = mean(ccf_seg);
    time_shift = (-(seg_length-1):1:(seg_length-1)) / fs;
    
    % NEW: Restrict the search window to a physiological range (-2s to +2s)
    valid_idx = find(time_shift >= -2 & time_shift <= 2);
    
    % Find the maximum value only within that valid window
    [CVAL, max_idx_relative] = max(avg_ccf(valid_idx)); 
    
    % Map the relative index back to the actual time shift
    TS = time_shift(valid_idx(max_idx_relative)); 
end
fff1= figure; %[output:1d2716c2]
subplot(3,1,1); plot(time_EO, AP_EO_filt); title('AP Displacement EO'); ylabel('mm'); %[output:1d2716c2]
subplot(3,1,2); plot(time_EO, SOL_EO_filt); title('SOL EMG EO'); ylabel('mV'); ylim([0,100]); %[output:1d2716c2]
subplot(3,1,3); plot(time_EO, TA_EO_filt); title('TA EMG EO'); xlabel('Time (s)'); ylabel('mV'); %[output:1d2716c2]
saveas(fff1, 'Fig111_TimeSeries_EO.png'); %[output:1d2716c2]

fff=figure; %[output:3cf2bf6c]
subplot(3,1,1); plot(time_EC, AP_EC_filt); title('AP Displacement EC'); ylabel('mm'); %[output:3cf2bf6c]
subplot(3,1,2); plot(time_EC, SOL_EC_filt); title('SOL EMG EC'); ylabel('mV'); ylim([0,100]); %[output:3cf2bf6c]
subplot(3,1,3); plot(time_EC, TA_EC_filt); title('TA EMG EC'); xlabel('Time (s)'); ylabel('mV'); %[output:3cf2bf6c]
saveas(fff, 'Fig222_TimeSeries_EC.png'); %[output:3cf2bf6c]

[ccf_EO_SOL, t_ccf, CVAL_EO_SOL, TS_EO_SOL] = compute_ccf(SOL_EO_filt, AP_EO_filt, seg_length, num_segments, fs_emg);
[ccf_EO_TA,  ~,     CVAL_EO_TA,  TS_EO_TA]  = compute_ccf(TA_EO_filt,  AP_EO_filt, seg_length, num_segments, fs_emg);
[ccf_EC_SOL, ~,     CVAL_EC_SOL, TS_EC_SOL] = compute_ccf(SOL_EC_filt, AP_EC_filt, seg_length, num_segments, fs_emg);
[ccf_EC_TA,  ~,     CVAL_EC_TA,  TS_EC_TA]  = compute_ccf(TA_EC_filt,  AP_EC_filt, seg_length, num_segments, fs_emg);
[ccf_test,  ~,     CVAL_test,  TS_test]  = compute_ccf(TA_rope_filt,  SOL_rope_filt, seg_length, num_segments, fs_emg);

fprintf('\n=== TABLE 2: CCF VALUES ===\n'); %[output:634c7486]
fprintf('EO AP x SOL: CVAL=%.4f, TS=%.4f s\n', CVAL_EO_SOL, TS_EO_SOL); %[output:00ff3ec4]
fprintf('EO AP x TA:  CVAL=%.4f, TS=%.4f s\n', CVAL_EO_TA, TS_EO_TA); %[output:85d49ae9]
fprintf('EC AP x SOL: CVAL=%.4f, TS=%.4f s\n', CVAL_EC_SOL, TS_EC_SOL); %[output:44ca8ca0]
fprintf('EC AP x TA:  CVAL=%.4f, TS=%.4f s\n', CVAL_EC_TA, TS_EC_TA); %[output:424ecb42]
fprintf('EC test:  CVAL=%.4f, TS=%.4f s\n', CVAL_test, TS_test); %[output:220d6838]

%% SECTION 7: Figure Generation & Saving
disp('Generating and saving plots...'); %[output:84bdd04c]

% COP Y vs X Plots
fig1 = figure; plot(ML_EO_filt, AP_EO_filt); title('COP Displacement (Eyes Open)'); xlabel('ML (mm)'); ylabel('AP (mm)'); axis equal; %[output:7cc18646]
saveas(fig1, 'Fig1_COP_EO.png'); %[output:7cc18646]

fig4 = figure; plot(ML_EC_filt, AP_EC_filt); title('COP Displacement (Eyes Closed)'); xlabel('ML (mm)'); ylabel('AP (mm)'); axis equal; %[output:8e54c50f]
saveas(fig4, 'Fig4_COP_EC.png'); %[output:8e54c50f]

% Time Series EMG Plots
fig2_3 = figure;  %[output:7ea59e5e]
subplot(2,1,1); plot(time_EO, TA_EO_filt); title('TA EMG (Eyes Open)'); ylabel('mV'); %[output:7ea59e5e]
subplot(2,1,2); plot(time_EO, SOL_EO_filt); title('SOL EMG (Eyes Open)'); xlabel('Time (s)'); ylabel('mV');ylim([0 100]);    %[output:7ea59e5e]
saveas(fig2_3, 'Fig2_3_EMG_EO.png'); %[output:7ea59e5e]

fig5_6 = figure;  %[output:4df8c53a]
subplot(2,1,1); plot(time_EC, TA_EC_filt); title('TA EMG (Eyes Closed)'); ylabel('mV'); %[output:4df8c53a]
subplot(2,1,2); plot(time_EC, SOL_EC_filt); title('SOL EMG (Eyes Closed)'); xlabel('Time (s)'); ylabel('mV');ylim([0 100]);    %[output:4df8c53a]
saveas(fig5_6, 'Fig5_6_EMG_EC.png'); %[output:4df8c53a]

% CCF Plots
fig7_8 = figure;  %[output:45e858c5]
subplot(2,1,1); plot(t_ccf, ccf_EO_SOL); title('CCF AP vs SOL (Eyes Open)'); xlabel('Lag (s)'); ylabel('r'); %[output:45e858c5]
subplot(2,1,2); plot(t_ccf, ccf_EO_TA); title('CCF AP vs TA (Eyes Open)'); xlabel('Lag (s)'); ylabel('r'); %[output:45e858c5]
saveas(fig7_8, 'Fig7_8_CCF_EO.png'); %[output:45e858c5]

fig9_10 = figure;  %[output:0e4ed299]
subplot(2,1,1); plot(t_ccf, ccf_EC_SOL); title('CCF AP vs SOL (Eyes Closed)'); xlabel('Lag (s)'); ylabel('r'); %[output:0e4ed299]
subplot(2,1,2); plot(t_ccf, ccf_EC_TA); title('CCF AP vs TA (Eyes Closed)'); xlabel('Lag (s)'); ylabel('r'); %[output:0e4ed299]
saveas(fig9_10, 'Fig9_10_CCF_EC.png'); %[output:0e4ed299]

%% SECTION 8: Interactive Perturbation Analysis
disp('=== PERTURBATION ANALYSIS ==='); %[output:5047bb15]
time_rope = (0:length(AP_rope_filt)-1) / fs_emg;

fig11 = figure('Name', 'Perturbation Analysis');  %[output:833ba277]
subplot(3,1,1); plot(time_rope, AP_rope_filt); title('AP Displacement'); ylabel('mm'); %[output:833ba277]
subplot(3,1,2); plot(time_rope, SOL_rope_filt); title('SOL EMG'); ylabel('mV'); ylim([0, 200]); %[output:833ba277]
subplot(3,1,3); plot(time_rope, TA_rope_filt); title('TA EMG'); xlabel('Time (s)'); ylabel('mV'); %[output:833ba277]
saveas(fig11, 'Fig11_Perturbed_Aligned.png'); % Save aligned figure before clicking [cite: 407] %[output:833ba277]

disp('1. Look at the Perturbed Standing plot (Fig 11).'); %[output:8dbcfdf6]
disp('2. Click precisely on the ONSET of the SOL response for each of the 3 pulls.'); %[output:0215d21b]
[sol_onsets, ~] = ginput(3); % [cite: 288] %[output:833ba277]

disp('3. Click precisely on the ONSET of the TA response for each of the 3 pulls.'); %[output:99260ee2]
[ta_onsets, ~] = ginput(3); % [cite: 288] %[output:833ba277]

disp('4. Click precisely on the PEAK AP displacement for each of the 3 pulls.'); %[output:96c29ee5]
[ap_peaks_time, ap_peaks_val] = ginput(3); % [cite: 289] %[output:833ba277]

% Calculate differentials
sol_diffs = sol_onsets - ap_peaks_time;
ta_diffs = ta_onsets - ap_peaks_time;

fprintf('\n=== TABLE 3: PERTURBED AVERAGES ===\n'); %[output:09feee94]
fprintf('Average Max AP Displacement: %.2f mm\n', mean(ap_peaks_val)); % [cite: 290] %[output:79e848f2]
fprintf('Average Time Diff (SOL onset to APmax): %.4f s\n', mean(sol_diffs)); % [cite: 290] %[output:19997635]
fprintf('Average Time Diff (TA onset to APmax): %.4f s\n', mean(ta_diffs)); % [cite: 290] %[output:48b74e9c]

% Final Reporting with Mean and Standard Deviation 
fprintf('\n=== TABLE 3: PERTURBED AVERAGES (n=3) ===\n'); %[output:7f537188]
fprintf('APmax: Mean = %.2f mm, SD = %.2f mm\n', mean(ap_peaks_val), std(ap_peaks_val)); %[output:3671de64]
fprintf('Time Diff (SOL onset to APmax): Mean = %.4f s, SD = %.4f s\n', mean(sol_diffs), std(sol_diffs)); %[output:00f8dd81]
fprintf('Time Diff (TA onset to APmax): Mean = %.4f s, SD = %.4f s\n', mean(ta_diffs), std(ta_diffs)); %[output:0ba4a18f]

disp('Processing complete! All files saved successfully.'); %[output:58fa1444]

